package org.eclipse.kura.util.base;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class ToHexStringTest {

    private byte[] bytes;
    private String hexString;
    private byte[] parsedBytes;
    private Exception occurredException;

    @Test
    public void emptyArrayIsConvertedToEmptyString() {
        givenBytes();

        whenToHexStringIsCalled();

        thenNoExceptionOccurred();
        thenHexStringIs("");
    }

    @Test
    public void singleByteIsConvertedToTwoDigits() {
        givenBytes(0x7B);

        whenToHexStringIsCalled();

        thenNoExceptionOccurred();
        thenHexStringIs("7b");
    }

    @Test
    public void lowValueBytesArePaddedWithLeadingZero() {
        givenBytes(0x00, 0x01, 0x0A, 0x0F);

        whenToHexStringIsCalled();

        thenNoExceptionOccurred();
        thenHexStringIs("00010a0f");
    }

    @Test
    public void negativeBytesAreConvertedAsUnsigned() {
        givenBytes(0x80, 0xAB, 0xFE, 0xFF);

        whenToHexStringIsCalled();

        thenNoExceptionOccurred();
        thenHexStringIs("80abfeff");
    }

    @Test
    public void lettersAreLowercase() {
        givenBytes(0xAB, 0xCD, 0xEF);

        whenToHexStringIsCalled();

        thenNoExceptionOccurred();
        thenHexStringIs("abcdef");
    }

    @Test
    public void byteOrderIsPreserved() {
        givenBytes(0x01, 0x23, 0x45, 0x67, 0x89, 0xAB, 0xCD, 0xEF);

        whenToHexStringIsCalled();

        thenNoExceptionOccurred();
        thenHexStringIs("0123456789abcdef");
    }

    @Test
    public void boundaryValuesAreConverted() {
        givenBytes(Byte.MIN_VALUE, Byte.MAX_VALUE);

        whenToHexStringIsCalled();

        thenNoExceptionOccurred();
        thenHexStringIs("807f");
    }

    @Test
    public void everyByteValueSurvivesRoundTripWithParseHexBinary() {
        givenAllPossibleByteValues();

        whenToHexStringIsCalled();
        whenHexStringIsParsedBack();

        thenNoExceptionOccurred();
        thenHexStringHasLength(512);
        thenParsedBytesMatchOriginalBytes();
    }

    @Test
    public void nullArrayIsRejected() {
        givenNullBytes();

        whenToHexStringIsCalled();

        thenExceptionOccurred(NullPointerException.class);
        thenNoHexStringIsReturned();
    }

    private void givenBytes(final int... values) {
        this.bytes = new byte[values.length];
        for (int i = 0; i < values.length; i++) {
            this.bytes[i] = (byte) values[i];
        }
    }

    private void givenAllPossibleByteValues() {
        this.bytes = new byte[256];
        for (int i = 0; i < this.bytes.length; i++) {
            this.bytes[i] = (byte) i;
        }
    }

    private void givenNullBytes() {
        this.bytes = null;
    }

    private void whenToHexStringIsCalled() {
        try {
            this.hexString = TypeUtil.toHexString(this.bytes);
        } catch (Exception e) {
            this.occurredException = e;
        }
    }

    private void whenHexStringIsParsedBack() {
        try {
            this.parsedBytes = TypeUtil.parseHexBinary(this.hexString);
        } catch (Exception e) {
            this.occurredException = e;
        }
    }

    private void thenHexStringIs(final String expected) {
        assertEquals(expected, this.hexString);
    }

    private void thenHexStringHasLength(final int expectedLength) {
        assertNotNull(this.hexString);
        assertEquals(expectedLength, this.hexString.length());
    }

    private void thenParsedBytesMatchOriginalBytes() {
        assertArrayEquals(this.bytes, this.parsedBytes);
    }

    private void thenNoHexStringIsReturned() {
        assertNull(this.hexString);
    }

    private void thenNoExceptionOccurred() {
        assertNull(this.occurredException);
    }

    private void thenExceptionOccurred(final Class<? extends Exception> expectedException) {
        assertNotNull(this.occurredException);
        assertEquals(expectedException, this.occurredException.getClass());
    }
}
